}

/// Includes destroyed gems.
int gems_found()
{
    return static_cast<int>(you.gems_found.count());
}

int gems_lost()
{
    int count = 0;
    for (int i = 0; i < NUM_GEM_TYPES; i++)
        if (you.gems_found[i] && you.gems_shattered[i])
            count += 1;
    return count;
}

int gems_held_intact()
{
    return gems_found() - gems_lost();
}

