static unique_ptr<targeter> _get_scroll_targeter(scroll_type which_scroll)
{
    // blinking handled elsewhere
    switch (which_scroll)
    {
    case SCR_FEAR:
        return find_spell_targeter(SPELL_CAUSE_FEAR, 1000, LOS_RADIUS);
    // Indicate the knockback radius differently than the butterfly radius.
    case SCR_BUTTERFLIES:
        return make_unique<targeter_radius>(&you, LOS_NO_TRANS, 5, 0, 0, 2);
    case SCR_SUMMONING:
        // TODO: shadow creatures targeter doesn't handle band placement very
        //       well, so this is an overestimate.
        return make_unique<targeter_maybe_radius>(&you, LOS_NO_TRANS, 5, 0, 1);
    case SCR_VULNERABILITY:
    case SCR_IMMOLATION:
        return make_unique<targeter_finite_will>();
    case SCR_SILENCE:
        return find_spell_targeter(SPELL_SILENCE, 30, LOS_RADIUS);
    case SCR_TORMENT:
        return make_unique<targeter_torment>();
    case SCR_POISON:
        return make_unique<targeter_poison_scroll>();
    default:
        return nullptr;
    }
}

static bool _scroll_targeting_check(scroll_type scroll, dist *target)
{
    // TODO: restructure so that spell scrolls call your_spells, and targeting
    // is handled automatically for such scrolls
    if (target && target->needs_targeting())
    {
        direction_chooser_args args;
        unique_ptr<targeter> hitfunc = _get_scroll_targeter(scroll);
        if (!hitfunc)
            return true; // sanity check
        if (scroll == SCR_FEAR)
        {
            // TODO: can't these be rolled in with the targeter somehow? Will
            // a fear (etc) targeter ever not have this?
            args.get_desc_messages_func = targeter_addl_desc_messages(SPELL_CAUSE_FEAR, 1000,
                get_spell_flags(SPELL_CAUSE_FEAR), hitfunc.get());
        }
        else if (scroll == SCR_VULNERABILITY || scroll == SCR_IMMOLATION)
            args.get_desc_messages_func = _desc_finite_wl;
        else if (scroll == SCR_TORMENT)
            args.get_desc_messages_func = _desc_res_torment;

        args.mode = TARG_ANY;
        args.self = confirm_prompt_type::cancel;
        args.hitfunc = hitfunc.get();
        scroll_targeting_behaviour beh;
        args.behaviour = &beh;

        direction(*target, args);
        return target->isValid && !target->isCancel;
    }
    else
        return true;
}

bool scroll_has_targeter(scroll_type which_scroll)
{
    switch (which_scroll)
    {
    case SCR_BLINKING:
    case SCR_FEAR:
    case SCR_SUMMONING:
    case SCR_BUTTERFLIES:
    case SCR_VULNERABILITY:
    case SCR_IMMOLATION:
    case SCR_POISON:
    case SCR_SILENCE:
    case SCR_TORMENT:
        return true;
    default:
        return false;
    }
}

// If needed, check whether there are hostiles in range that would be affected.
// True means that the scroll either doesn't have such a check, or that there
// are relevant enemies in range. False means that the check failed.
bool scroll_hostile_check(scroll_type which_scroll)
{
    // cf spell_no_hostile_in_range
    if (!in_bounds(you.pos()) || !you.on_current_level)
        return false;

    // no hostile check
    if (which_scroll == SCR_SUMMONING
        || which_scroll == SCR_BLINKING
        || which_scroll == SCR_BUTTERFLIES)
    {
        return true;
    }

    unique_ptr<targeter> hitfunc = _get_scroll_targeter(which_scroll);
    if (!hitfunc)
        return true; // no checks for these

    // all scrolls that have a targeter are los radius
    for (radius_iterator ri(you.pos(), LOS_NO_TRANS, true);
         ri; ++ri)
    {
        const monster* mon = monster_at(*ri);
        if (!mon
            || !mon->visible_to(&you)
            // Plants/fungi don't count.
            || (!mons_is_threatening(*mon) || mon->wont_attack())
                && !mons_class_is_test(mon->type))
        {
            continue;
        }

        if (which_scroll == SCR_POISON)
        {
            monster_info mi(mon);
            if (get_resist(mi.mresists, MR_RES_POISON) <= 0)
                return true;
        }

        if (hitfunc->valid_aim(*ri) && hitfunc->is_affected(*ri) != AFF_NO)
            return true;
    }
    // nothing found: check fails
    return false;
}

static bool _scroll_has_forced_targeter(scroll_type scroll)
{
    return Options.always_use_static_scroll_targeters
            || Options.force_scroll_targeter.count(scroll) > 0;
}

/**
 * Read the provided scroll.
 *
 * Check to see if the player can read the provided scroll, and if so,
 * reads it. If no scroll is provided, prompt for a scroll.
 *
 * @param scroll The scroll to be read.
 * @param target targeting information, used by the quiver API
 */
bool read(item_def* scroll, dist *target)
{
    string failure_reason = cannot_read_item_reason(scroll);
    if (!failure_reason.empty())
    {
        mpr(failure_reason);
        return false;
    }
    ASSERT(scroll);

    const scroll_type which_scroll = static_cast<scroll_type>(scroll->sub_type);
    // Handle player cancels before we waste time
    if (item_type_known(*scroll))
    {
        const bool hostile_check = scroll_hostile_check(which_scroll);
        bool penance = god_hates_item(*scroll);
        string verb_object = "read the " + scroll->name(DESC_DBNAME);

        string penance_prompt = make_stringf("Really %s? This action would"
                                             " place you under penance%s!",
                                             verb_object.c_str(),
                                             hostile_check ? ""
                    : " and you can't even see any enemies this would affect");

        targeter_radius hitfunc(&you, LOS_NO_TRANS);

        const bool bad_item = (is_dangerous_item(*scroll, true)
                                    || is_bad_item(*scroll))
                            && Options.bad_item_prompt
                            // Don't double-prompt if we're already asking for confirmation.
                            && !_scroll_has_forced_targeter(static_cast<scroll_type>(scroll->sub_type));

        if (stop_attack_prompt(hitfunc, verb_object.c_str(),
                               [which_scroll] (const actor* m)
                               {
                                   return _scroll_will_harm(which_scroll, *m);
                               },
                               nullptr, nullptr))
        {
            return false;
        }
        else if (penance && !yesno(penance_prompt.c_str(), false, 'n'))
        {
            canned_msg(MSG_OK);
            return false;
        }
        else if (bad_item
                 && !yesno(make_stringf("Really %s?%s",
                                        verb_object.c_str(),
                                        hostile_check ? ""
                        : " You can't even see any enemies this would affect."
                                        ).c_str(),
                           false, 'n'))
        {
            canned_msg(MSG_OK);
            return false;
        }
        else if (!bad_item && !hostile_check && !yesno(make_stringf(
            "You can't see any enemies this would affect, really %s?",
                                        verb_object.c_str()).c_str(),
                                                false, 'n'))
        {
            // is this too nanny dev?
            canned_msg(MSG_OK);
            return false;
        }
    }

    const bool nearby_mons = there_are_monsters_nearby(true, true, false);
    if (you.unrand_equipped(UNRAND_VICTORY, true)
        && !you.props.exists(VICTORY_CONDUCT_KEY))
    {
        item_def *item = you.equipment.get_first_slot_item(SLOT_BODY_ARMOUR, true);
        string unrand_prompt = make_stringf("Really read with monsters nearby "
                                            "while wearing %s?",
                                            item->name(DESC_THE, false, true,
                                                       false).c_str());

        if (item->props[VICTORY_STAT_KEY].get_int() > 0
            && nearby_mons
            && !yesno(unrand_prompt.c_str(), false, 'n'))
        {
            canned_msg(MSG_OK);
            return false;
        }
    }

    // Ok - now we FINALLY get to read a scroll !!! {dlb}
    you.turn_is_over = true;

    const int prev_quantity = scroll->quantity;
    int link = in_inventory(*scroll) ? scroll->link : -1;
    const bool alreadyknown = item_type_known(*scroll);

    if (alreadyknown
        && scroll_has_targeter(which_scroll)
        && which_scroll != SCR_BLINKING) // blinking calls its own targeter
    {
        dist force_target;
        if (alreadyknown && !target && _scroll_has_forced_targeter(which_scroll))
            target = &force_target;

        if (!_scroll_targeting_check(which_scroll, target))
        {
            // a targeter can't be used for unid'd or uncancellable scrolls, so
            // we can skip the rest of the function
            you.turn_is_over = false;
            return false;
        }
    }

    const bool is_loud = you.has_mutation(MUT_BOOMING_VOICE)
                         && there_are_monsters_nearby(true, true, false);
    const coord_def original_pos = you.pos();

    // For cancellable scrolls leave printing this message to their
    // respective functions.
    const string pre_succ_msg =
            make_stringf("As you %s the %s, it %s.",
                          is_loud ? "thunderously recite" : "read",
                          scroll->name(DESC_QUALNAME).c_str(),
                         which_scroll == SCR_FOG ? "dissolves into smoke" : "crumbles to dust");
    if (!_is_cancellable_scroll(which_scroll))
    {
        mpr(pre_succ_msg);
        // Actual removal of scroll done afterwards. -- bwr
    }

    const bool dangerous = player_in_a_dangerous_place();

    // ... but some scrolls may still be cancelled afterwards.
    bool cancel_scroll = false;
    bool bad_effect = false; // for Xom: result is bad (or at least dangerous)

    switch (which_scroll)
    {
    case SCR_BLINKING:
    {
        const ZhArg reason = you.no_tele_display_reason(true);
        if (!reason.canonical.empty())
        {
            mpr(pre_succ_msg);
            mpr(ZhMessage{"", reason.canonical, reason.localized});
            break;
        }

        if (!alreadyknown)
        {
            mpr(pre_succ_msg);

            run_uncancel(UNC_BLINKING);
        }
        else
        {
            cancel_scroll = (controlled_blink(alreadyknown, target)
                == spret::abort);

            if (!cancel_scroll)
                mpr(pre_succ_msg); // ordering is iffy but w/e
        }
    }
        break;

    case SCR_TELEPORTATION:
    {
        // you_teleport already handles much of this, but this allows a more
        // robust message for unidentified tele scrolls read with -tele
        const ZhArg reason = you.no_tele_display_reason();
        if (!reason.canonical.empty())
        {
            mpr(pre_succ_msg);
            mpr(ZhMessage{"", reason.canonical, reason.localized});
            break;
        }

        you_teleport();
    }
        break;

    case SCR_ACQUIREMENT:
        if (!alreadyknown)
            mpr("This is a scroll of acquirement!");

        // included in default force_more_message
        // Identify it early in case the player checks the '\' screen.
        identify_item(*scroll);

        if (feat_eliminates_items(env.grid(you.pos())))
        {
            mpr("Anything you acquired here would fall and be lost!");
            cancel_scroll = true;
            break;
        }

        cancel_scroll = !acquirement_menu();
        break;

    case SCR_FEAR:
        mpr("You assume a fearsome visage.");
        mass_enchantment(ENCH_FEAR, 1000);
        break;

    case SCR_NOISE:
        noisy(25, you.pos(), "You hear a loud clanging noise!");
        break;

    case SCR_SUMMONING:
        cancel_scroll = summon_shadow_creatures() == spret::abort
                        && alreadyknown;
        break;

    case SCR_BUTTERFLIES:
        cancel_scroll = summon_butterflies() == spret::abort && alreadyknown;
        break;

    case SCR_FOG:
    {
        auto smoke = random_smoke_type();
        big_cloud(smoke, &you, you.pos(), 50, 8 + random2(8));
        break;
    }

    case SCR_REVELATION:
        magic_mapping(GDM, 100, false, false, false, false, false);
        you.duration[DUR_REVELATION] = you.time_taken + 1;
        break;

    case SCR_TORMENT:
        torment(&you, TORMENT_SCROLL, you.pos());

        // This is only naughty if you know you're doing it.
        did_god_conduct(DID_EVIL, 10, item_type_known(*scroll));
        bad_effect = !you.res_torment();
        break;

    case SCR_IMMOLATION:
    {
        bool had_effect = false;
        for (monster_near_iterator mi(you.pos(), LOS_NO_TRANS); mi; ++mi)
        {
            if (mons_invuln_will(**mi))
                continue;

            // Jivya is a killjoy when it comes to slime bombing.
            if (have_passive(passive_t::neutral_slimes) && mons_is_slime(**mi))
                continue;

            if (mi->add_ench(mon_enchant(ENCH_INNER_FLAME, &you)))
                had_effect = true;
        }

        if (had_effect)
            mpr("The creatures around you are filled with an inner flame!");
        else
            mpr("The air around you briefly surges with heat, but it dissipates.");

        bad_effect = true;
        break;
    }

    case SCR_POISON:
    {
        const spret result = scroll_of_poison(!alreadyknown);
        cancel_scroll = result == spret::abort;
        if (!cancel_scroll)
            mpr(pre_succ_msg);
        // amusing to Xom, at least
        bad_effect = result == spret::success && !player_res_poison();
        break;
    }

    case SCR_ENCHANT_WEAPON:
        if (!alreadyknown)
        {
            mpr(pre_succ_msg);
            mpr("It is a scroll of enchant weapon.");
            // included in default force_more_message (to show it before menu)

            run_uncancel(UNC_ENCHANT_WEAPON);
        }
        else
            cancel_scroll = !_handle_enchant_weapon(alreadyknown, pre_succ_msg);

        break;

    case SCR_BRAND_WEAPON:
        if (!alreadyknown)
        {
            mpr(pre_succ_msg);
            mpr("It is a scroll of brand weapon.");
            // included in default force_more_message (to show it before menu)

            run_uncancel(UNC_BRAND_WEAPON);
        }
        else
            cancel_scroll = !_handle_brand_weapon(alreadyknown, pre_succ_msg);

        break;

    case SCR_IDENTIFY:
        if (!alreadyknown)
        {
            mpr(pre_succ_msg);
            mpr("It is a scroll of identify.");
            // included in default force_more_message (to show it before menu)
            // Do this here so it doesn't turn up in the ID menu.
            identify_item(*scroll);

            run_uncancel(UNC_IDENTIFY);
        }
        else
            cancel_scroll = !_identify(alreadyknown, pre_succ_msg);

        break;

    case SCR_ENCHANT_ARMOUR:
        if (!alreadyknown)
        {
            mpr(pre_succ_msg);
            mpr("It is a scroll of enchant armour.");
            // included in default force_more_message (to show it before menu)

            run_uncancel(UNC_ENCHANT_ARMOUR);
        }
        else
            cancel_scroll = !_handle_enchant_armour(alreadyknown, pre_succ_msg);

        break;
#if TAG_MAJOR_VERSION == 34
    case SCR_CURSE_WEAPON:
    case SCR_CURSE_ARMOUR:
    case SCR_CURSE_JEWELLERY:
    case SCR_RECHARGING:
    case SCR_RANDOM_USELESSNESS:
    case SCR_HOLY_WORD:
    {
        mpr("This item has been removed, sorry!");
        cancel_scroll = true;
        break;
    }
#endif

    case SCR_SILENCE:
        cast_silence(30);
        break;

    case SCR_VULNERABILITY:
        _vulnerability_scroll();
        break;

    case SCR_AMNESIA:
        if (!alreadyknown)
        {
            mpr(pre_succ_msg);
            mpr("It is a scroll of amnesia.");
            // included in default force_more_message (to show it before menu)
        }
        if (you.spell_no == 0 || you.has_mutation(MUT_INNATE_CASTER))
        {
            mpr("You feel forgetful for a moment.");
            break;
        }

        if (!alreadyknown)
            run_uncancel(UNC_AMNESIA);
        else
            cancel_scroll = !_handle_amnesia(alreadyknown);

        break;

    default:
        mpr("Read a buggy scroll, please report this.");
        break;
    }

    if (cancel_scroll)
        you.turn_is_over = false;

    identify_item(*scroll);

    string scroll_name = scroll->name(DESC_QUALNAME);

    if (!cancel_scroll)
    {
        if (in_inventory(*scroll))
            dec_inv_item_quantity(link, 1);
        else
            dec_mitm_item_quantity(scroll->index(), 1);

        count_action(CACT_USE, OBJ_SCROLLS);
        count_action(CACT_READ, scroll->sub_type);

        if (is_loud)
            noisy(40, original_pos, MID_PLAYER);
    }

    if (!alreadyknown
        && which_scroll != SCR_BRAND_WEAPON
        && which_scroll != SCR_ENCHANT_WEAPON
        && which_scroll != SCR_IDENTIFY
        && which_scroll != SCR_ENCHANT_ARMOUR
        && which_scroll != SCR_AMNESIA
        && which_scroll != SCR_ACQUIREMENT)
    {
        mprf("It %s %s.",
             scroll->quantity < prev_quantity ? "was" : "is",
             article_a(scroll_name).c_str());
    }

    if (!alreadyknown)
    {
        if (you.unrand_equipped(UNRAND_DELATRAS_GLOVES))
        {
            mpr("The energy of discovery flows from your fingertips!");
            potionlike_effect(POT_MAGIC, 40);
        }

        if (dangerous)
        {
            // Xom loves it when you read an unknown scroll and there is a
            // dangerous monster nearby... (though not as much as potions
            // since there are no *really* bad scrolls, merely useless ones).
            xom_is_stimulated(bad_effect ? 100 : 50);
        }
    }

    // Reading with hostile visible mons nearby resets unrand "Victory" stats.
    if (you.unrand_equipped(UNRAND_VICTORY, true)
        && nearby_mons
        && !cancel_scroll)
    {
        you.props[VICTORY_CONDUCT_KEY] = true;
    }

    if (!alreadyknown)
        auto_assign_item_slot(*scroll);
    return true;
}

class targeter_invisibility : public targeter_multimonster
{
public:
    targeter_invisibility();
    bool affects_monster(const monster_info& mon) override;
};

targeter_invisibility::targeter_invisibility()
    : targeter_multimonster(&you)
{
}

bool targeter_invisibility::affects_monster(const monster_info& mon)
{
    return !mon.is(MB_FIREWOOD) && !mon.can_see_invisible();
}

static vector<ZhArg> _desc_see_invis(const monster_info& mi)
{
    vector<ZhArg> r;
    if (mi.can_see_invisible())
        r.push_back(zh_message_arg("effect", "target.monster.callback.see_invisible"));
    else if (!mi.is(MB_CANT_SEE_YOU))
    {
        if (!you.backlit())
            r.push_back(zh_message_arg("effect", "target.monster.callback.lose_sight"));
        else
            r.push_back(zh_message_arg("effect", "target.monster.callback.cannot_see_invisible"));
    }
    return r;
}

// Show a targeter indicating what monsters would lose sight of the player if
// they went invisible right now, and return false if the player wishes to cancel.
bool invisibility_target_check(const char* prompt)
{
    bool found_any = false;
    bool found_susceptible = false;
    for (monster_near_iterator mi(&you); mi; ++mi)
    {
        if (!mi->wont_attack() && !mi->is_firewood())
        {
            found_any = true;
            if (!mi->can_see_invisible())
            {
                found_susceptible = true;
                break;
            }
        }
    }

    // Allow the player to go invisible outside of LoS of enemies with no prompt.
    // However, going invisible in LoS of only enemies with sInv is more likely
    // to be a mistake.
    if (!found_any)
        return true;
    if (!found_susceptible)
        return yesno("You can't see any enemy this would conceal you from. Use anyway?", true, 'n');

    direction_chooser_args args;
    unique_ptr<targeter> hitfunc = make_unique<targeter_invisibility>();
    args.get_desc_messages_func = _desc_see_invis;
    args.mode = TARG_ANY;
    args.self = confirm_prompt_type::cancel;
    args.hitfunc = hitfunc.get();
    args.target_prefix = prompt;
    scroll_targeting_behaviour beh;
    args.behaviour = &beh;

    dist target;
    direction(target, args);
    return target.isValid && !target.isCancel;
}

ZhArg cannot_put_on_talisman_display_reason(const item_def& talisman, bool temp)
{
    ASSERT(talisman.base_type == OBJ_TALISMANS);

    if (talisman.sub_type == TALISMAN_PROTEAN)
    {
        if (temp && you.skill(SK_SHAPESHIFTING) < 6)
        {
            return zh_message_arg("reason", "talisman.reason.unstable");
        }
        else if (species_apt(SK_SHAPESHIFTING) == UNUSABLE_SKILL)
            return zh_message_arg("reason", "talisman.reason.unusable_skill");
        else
            return {"reason", ZhArgType::Text, "", "", true};
    }

    const transformation trans = form_for_talisman(talisman);
    ZhArg form_unreason = cant_transform_display_reason(trans, false, temp);
    if (!form_unreason.canonical.empty())
    {
        form_unreason.canonical = lowercase_first(form_unreason.canonical);
        if (!form_unreason.supported)
            form_unreason.localized = form_unreason.canonical;
        return form_unreason;
    }

    if (you.form != you.default_form && temp)
        return zh_message_arg("reason", "talisman.reason.leave_form");

    if (trans == transformation::hive)
    {
        if (you_worship(GOD_OKAWARU))
            return zh_message_arg("reason", "talisman.reason.okawaru_allies");
        if (you.get_mutation_level(MUT_NO_LOVE))
            return zh_message_arg("reason", "talisman.reason.loveless");
    }

    return {"reason", ZhArgType::Text, "", "", true};
}

string cannot_put_on_talisman_reason(const item_def& talisman, bool temp)
{
    return cannot_put_on_talisman_display_reason(talisman, temp).canonical;
}

bool use_talisman(item_def& talisman)
{
    const ZhArg reason = cannot_put_on_talisman_display_reason(talisman);
    if (!reason.canonical.empty())
    {
        mpr(ZhMessage{"", reason.canonical, reason.localized});
        return false;
    }

    if (talisman.pos != ITEM_IN_INVENTORY && !room_in_inventory(talisman))
    {
        mpr(zh_message("talisman.reason.cannot_carry"));
        return false;
    }

    item_def& real_item = you.inv[_get_item_slot_maybe_with_move(talisman)];

    if (real_item.sub_type == TALISMAN_PROTEAN)
    {
        const talisman_type new_type = random_choose(TALISMAN_RIMEHORN,
                                                     TALISMAN_SCARAB,
                                                     TALISMAN_MEDUSA,
                                                     TALISMAN_SPORE);

        item_def transformed = real_item;
        transformed.sub_type = new_type;
        mpr(zh_message("talisman.protean.transforms",
            {zh_item_arg("item", real_item, DESC_YOUR),
             zh_item_base_arg("form", transformed)}));

        real_item.sub_type = new_type;
        seen_item(real_item);
        return use_talisman(real_item);
    }

    const transformation trans = you.active_talisman() == &real_item
                                    ? transformation::none
                                    : form_for_talisman(real_item);
    if (!check_transform_into(trans, false, &real_item))
        return false;
    if (transforming_is_unsafe(trans))
        return false;
    if (!i_feel_safe(true) && !yesno(zh_message("talisman.confirm.begin_transform"), true, 'n'))
    {
        canned_msg(MSG_OK);
        return false;
    }

    count_action(CACT_FORM, (int)trans);
    start_delay<TransformDelay>(trans, &real_item);
    if (god_despises_item(real_item, you.religion))
        excommunication();
    you.turn_is_over = true;
    return true;
}

#ifdef USE_TILE
// Interactive menu for item drop/use.

void tile_item_pickup(int idx, bool part)
{
    if (item_is_stationary(env.item[idx]))
    {
        mpr("You can't pick that up.");
        return;
    }

    int quantity = env.item[idx].quantity;
    if (part && quantity > 1)
    {
        quantity = prompt_for_int("Pick up how many? ", true);
        if (quantity < 1)
        {
            canned_msg(MSG_OK);
            return;
        }
        if (quantity > env.item[idx].quantity)
            quantity = env.item[idx].quantity;
    }
    pickup_single_item(idx, quantity);
}

void tile_item_drop(int idx, bool partdrop)
{
    if (!check_warning_inscriptions(you.inv[idx], OPER_DROP))
    {
        canned_msg(MSG_OK);
        return;
    }
    int quantity = you.inv[idx].quantity;
    if (partdrop && quantity > 1)
    {
        quantity = prompt_for_int("Drop how many? ", true);
        if (quantity < 1)
        {
            canned_msg(MSG_OK);
            return;
        }
        if (quantity > you.inv[idx].quantity)
            quantity = you.inv[idx].quantity;
    }
    drop_item(idx, quantity);
}

void tile_item_use(int idx)
{
    item_def &item = you.inv[idx];

    // Equipped?
    const bool equipped = item_is_equipped(item);

    if (item_ever_evokable(item))
    {
        if (check_warning_inscriptions(item, OPER_EVOKE))
            evoke_item(item);
        return;
    }

    const int type = item.base_type;

    // Use it
    switch (type)
    {

    case OBJ_MISSILES:
        if (check_warning_inscriptions(item, OPER_FIRE))
            quiver::slot_to_action(idx)->trigger(); // TODO: anything more interesting?
        return;

    case OBJ_TALISMANS:
        try_equip_item(item);
        return;

    case OBJ_WEAPONS:
    case OBJ_STAVES:
    case OBJ_ARMOUR:
    case OBJ_JEWELLERY:
        if (equipped)
            try_unequip_item(item);
        else
            try_equip_item(item);
        return;

    case OBJ_SCROLLS:
        if (check_warning_inscriptions(item, OPER_READ))
            read(&you.inv[idx]);
        return;

    case OBJ_POTIONS:
        if (check_warning_inscriptions(item, OPER_QUAFF))
            drink(&you.inv[idx]);
        return;

    default:
        return;
    }
}
#endif

